try:
    # The overview returns dict-like object
    overview_data = rlm.harness.overview()
    print(f"\nOverview type: {type(overview_data)}")

    # Convert to dict if needed
    if hasattr(overview_data, 'items'):
        for k, v in overview_data.items():
            if 'submit' in k.lower() or 'api' in k.lower():
                print(f"Key '{k}': {str(v)[:300]}...")
except Exception as e:
    print(f"Error getting overview: {e}")

# Try direct memory operations
print("\n=== Direct memory lookup ===")
